//! `omp config` — schema-driven settings inspection and persistence.
//!
//! Mirrors `packages/coding-agent/src/cli/config-cli.ts` over the *full*
//! upstream schema, not just the keys this binary consumes at runtime: the
//! snapshot in `settings-schema.snapshot.json` is generated by
//! `scripts/dump-settings-schema.ts` from `SETTINGS_SCHEMA`, so every key,
//! enum value and computed default is the upstream one.
//!
//! Effective values are read from the same layers the run path uses (global
//! `config.yml`, project `.omp/settings.json` + `.omp/config.yml`, then
//! `PI_CONFIG_FILES` and `--config` overlays, later winning). Writes always
//! target the global file: they re-read it under an advisory lock, apply only
//! this command's path and re-emit, so unknown keys and their order survive and
//! concurrent disjoint writes merge instead of clobbering each other. Comments
//! and formatting are not preserved — upstream re-serializes too.
//!
//! Boundaries: no editor action (upstream `config` has none either).

use std::collections::HashSet;
use std::ffi::OsStr;
use std::fs;
#[cfg(not(target_os = "linux"))]
use std::fs::File;
use std::fs::OpenOptions;
#[cfg(target_os = "linux")]
use std::os::linux::net::SocketAddrExt;
use std::os::unix::fs::{MetadataExt, OpenOptionsExt};
#[cfg(target_os = "linux")]
use std::os::unix::net::{SocketAddr, UnixDatagram};
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use std::sync::LazyLock;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use serde::Deserialize;
use serde_json::{Map, Value as Json};

use crate::config::{self, env_config_files, json_to_value};
use crate::dirs;
use crate::yaml::{self, Value};
use crate::{Error, Result};

/// Printed instead of a credential value in human output only.
const REDACTED: &str = "********";

/// Bound for chained symlinks on the write path.
const SYMLINK_HOPS: usize = 32;

const PROVIDER_LIMITS_PATH: &str = "providers.maxInFlightRequests";
/// Printed after every usage or unknown-key error, like the TypeScript CLI.
const LIST_HINT: &str = "Run 'omp config list' to see available keys";

// ═══════════════════════════════════════════════════════════════════════════
// Schema snapshot
// ═══════════════════════════════════════════════════════════════════════════

#[derive(Deserialize)]
struct Snapshot {
	#[allow(dead_code, reason = "provenance is checked by the drift script, not at runtime")]
	provenance: Provenance,
	settings: Vec<SettingDef>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(dead_code, reason = "documented provenance; the drift check runs in the generator")]
struct Provenance {
	source: String,
	source_sha256: String,
	/// Hash of the transitive local imports the defaults were read from.
	#[serde(default)]
	import_graph: Option<ImportGraph>,
	generator: String,
	git_revision: String,
}

#[derive(Deserialize)]
#[allow(dead_code, reason = "documented provenance; the drift check runs in the generator")]
struct ImportGraph {
	files: usize,
	sha256: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct SettingDef {
	path: String,
	#[serde(rename = "type")]
	kind: String,
	#[serde(default)]
	values: Option<Vec<String>>,
	#[serde(default)]
	default: Option<Json>,
	#[serde(default)]
	default_absent: bool,
	#[serde(default)]
	credential: bool,
	#[serde(default)]
	ui: Option<UiMeta>,
}

#[derive(Deserialize)]
#[allow(dead_code, reason = "settings-panel metadata the CLI does not print")]
struct UiMeta {
	tab: String,
	#[serde(default)]
	group: Option<String>,
	#[serde(default)]
	label: String,
	#[serde(default)]
	description: String,
}

static SETTINGS_SCHEMA: LazyLock<Snapshot> = LazyLock::new(|| {
	serde_json::from_str(include_str!("../settings-schema.snapshot.json"))
		.expect("settings schema snapshot is generated and valid JSON")
});

fn find_def(path: &str) -> Option<&'static SettingDef> {
	SETTINGS_SCHEMA.settings.iter().find(|def| def.path == path)
}

fn unknown_setting(path: &str) -> Error {
	Error::new(format!("Unknown setting: {path}\n\n{LIST_HINT}"))
}

// ═══════════════════════════════════════════════════════════════════════════
// Request
// ═══════════════════════════════════════════════════════════════════════════

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
	List,
	Get,
	Set,
	Reset,
	Path,
	InitXdg,
}

impl Action {
	pub const NAMES: [&'static str; 6] = ["list", "get", "set", "reset", "path", "init-xdg"];

	#[must_use]
	pub fn parse(raw: &str) -> Option<Self> {
		match raw {
			"list" => Some(Self::List),
			"get" => Some(Self::Get),
			"set" => Some(Self::Set),
			"reset" => Some(Self::Reset),
			"path" => Some(Self::Path),
			"init-xdg" => Some(Self::InitXdg),
			_ => None,
		}
	}
}

/// Unknown-action diagnostics, matching the upstream message and exit path.
pub fn unknown_action(raw: &str) -> Error {
	Error::new(format!(
		"Unknown config command: {raw}\nValid commands: {}",
		Action::NAMES.join(", ")
	))
}

pub struct Request {
	pub action: Action,
	pub key: Option<String>,
	pub value: Option<String>,
	pub json: bool,
	/// Project directory for the project settings layer (already absolute).
	pub cwd: PathBuf,
	/// `--config` overlays, later files winning.
	pub overlays: Vec<PathBuf>,
}

pub fn run(request: &Request, out: &mut impl Write) -> Result<()> {
	// `runConfigCommand` awaits `Settings.init()` before dispatching, and init
	// migrates legacy settings into config.yml. Running the same seed here means
	// `list`/`get` see migrated values exactly like upstream.
	init_legacy_migration()?;
	match request.action {
		Action::List => list(request, out),
		Action::Get => get(request, out),
		Action::Set => set(request, out),
		Action::Reset => reset(request, out),
		Action::Path => {
			writeln!(out, "{}", dirs::agent_dir().display())?;
			Ok(())
		},
		Action::InitXdg => init_xdg(out),
	}
}

// ═══════════════════════════════════════════════════════════════════════════
// Layers
// ═══════════════════════════════════════════════════════════════════════════

/// Effective settings: global config, project settings, then overlays.
fn merged(request: &Request) -> Result<Value> {
	merged_layers(&request.cwd, &request.overlays)
}

fn merged_layers(cwd: &Path, overlays: &[PathBuf]) -> Result<Value> {
	let mut merged = Value::Map(Vec::new());
	if let Some(base) = config::base_path() {
		let mut global = read_target(&base)?;
		migrate_settings(&mut global);
		merge(&mut merged, global);
	} else if let Some(mut legacy) = legacy_global_settings() {
		// Reached only when init could not seed (e.g. an unwritable config dir).
		migrate_settings(&mut legacy);
		merge(&mut merged, legacy);
	}
	merge(&mut merged, project_layer(cwd)?);
	for path in env_config_files().iter().chain(overlays.iter()) {
		let resolved = config::resolve_layer_path(cwd, path);
		if !resolved.is_file() {
			return Err(Error::new(format!("config file not found: {}", resolved.display())));
		}
		let mut overlay = read_target(&resolved)?;
		migrate_settings(&mut overlay);
		merge(&mut merged, overlay);
	}
	Ok(merged)
}

/// Effective value of one setting after layers, defaults and path-scoped
/// resolution: exactly what `omp config get <key> --json` reports, as JSON.
///
/// Other commands that need a setting the run path does not model (for example
/// `worktree.base`) call this instead of re-reading config files.
pub fn effective_setting(cwd: &Path, overlays: &[PathBuf], key: &str) -> Result<Option<Json>> {
	let def = find_def(key).ok_or_else(|| unknown_setting(key))?;
	let merged = merged_layers(cwd, overlays)?;
	Ok(effective_value(&merged, def, cwd).map(|value| value_to_json(&value)))
}

/// `agent/settings.json` is the legacy global settings file, superseded once a
/// main YAML exists; read without migrating, like the run path does.
fn legacy_global_settings() -> Option<Value> {
	read_legacy_source().map(|source| source.value)
}

/// Legacy `settings.json` plus the identity of the exact bytes that were read,
/// so the archive step can prove nothing changed in between.
struct LegacySource {
	path: PathBuf,
	identity: (u64, u64, Option<SystemTime>),
	/// Present when `settings.json` is a symlink: the archive recreates the link
	/// instead of copying the target, exactly like upstream's rename.
	link: Option<PathBuf>,
	value: Value,
}

fn read_legacy_source() -> Option<LegacySource> {
	let path = dirs::agent_dir().join("settings.json");
	let link = fs::symlink_metadata(&path)
		.ok()
		.filter(|meta| meta.file_type().is_symlink())
		.and_then(|_| fs::read_link(&path).ok());
	let file = fs::File::open(&path).ok()?;
	let meta = file.metadata().ok()?;
	let identity = (meta.ino(), meta.len(), meta.modified().ok());
	let mut text = String::new();
	io::BufReader::new(file).read_to_string(&mut text).ok()?;
	let json = jsonc_to_json(&text)?;
	Some(LegacySource {
		path,
		identity,
		link,
		value: json_to_value(&json),
	})
}

/// Project layer: every capability provider that contributes project settings,
/// merged in provider-priority order (builtin 100, claude 80, gemini 60,
/// opencode 55, cursor 50; codex 70 is skipped upstream) exactly like `#readProjectSettings`, then migrated.
fn project_layer(cwd: &Path) -> Result<Value> {
	let dir = dirs::project_config_dir(cwd);
	let mut layer = Value::Map(Vec::new());
	let merge_json = |layer: &mut Value, path: &Path, jsonc: bool| {
		let Ok(mut text) = fs::read_to_string(path) else { return };
		if jsonc {
			text = substitute_config_vars(&text, path);
		}
		let parsed = if jsonc { jsonc_to_json(&text) } else { serde_json::from_str::<Json>(&text).ok() };
		match parsed {
			Some(json) => merge(layer, drop_group_shadows(&json_to_value(&json))),
			None => eprintln!("warning: skipping invalid settings {}", path.display()),
		}
	};
	merge_json(&mut layer, &dir.join("settings.json"), false);
	let project_config = dir.join(dirs::MAIN_CONFIG_FILENAMES[0]);
	let native_project = if project_config.is_file() {
		// Capability-provided project settings drop a scalar written where the
		// schema expects a group, in `.omp/config.yml` just like `settings.json`.
		Some(drop_group_shadows(&read_target(&project_config)?))
	} else {
		None
	};
	if let Some(native) = &native_project {
		merge(&mut layer, native.clone());
	}
	merge_json(&mut layer, &cwd.join(".claude").join("settings.json"), false);
	merge_json(&mut layer, &cwd.join(".gemini").join("settings.json"), false);
	for name in ["opencode.json", "opencode.jsonc"] {
		merge_json(&mut layer, &cwd.join(name), true);
	}
	for name in ["opencode.json", "opencode.jsonc"] {
		merge_json(&mut layer, &dir.join(name), true);
	}
	merge_json(&mut layer, &cwd.join(".cursor").join("settings.json"), false);
	// Only the native file's model roles are re-merged after every provider.
	if let Some(roles) = native_project.as_ref().and_then(|native| native.get("modelRoles").cloned()) {
		merge(&mut layer, Value::Map(vec![("modelRoles".to_string(), roles)]));
	}
	filter_project_model_roles(&mut layer);
	migrate_settings(&mut layer);
	// The web-search endpoint and its credentials are host settings; the runtime
	// ignores project `searxng.*` (see `Config::apply_project_layers`), so the
	// effective view must not report a repository-controlled endpoint either.
	if let Value::Map(entries) = &mut layer {
		entries.retain(|(key, _)| key != "searxng");
	}
	Ok(layer)
}

/// Strip `//` and `/* */` comments from JSONC without touching string bodies.
fn jsonc_to_json(text: &str) -> Option<Json> {
	let mut out = String::with_capacity(text.len());
	let mut chars = text.chars().peekable();
	let mut in_string = false;
	let mut escaped = false;
	while let Some(ch) = chars.next() {
		if in_string {
			out.push(ch);
			if escaped {
				escaped = false;
			} else if ch == '\\' {
				escaped = true;
			} else if ch == '"' {
				in_string = false;
			}
			continue;
		}
		match ch {
			'"' => {
				in_string = true;
				out.push(ch);
			},
			'/' => match chars.peek() {
				Some('/') => {
					for next in chars.by_ref() {
						if next == '\n' {
							out.push('\n');
							break;
						}
					}
				},
				Some('*') => {
					chars.next();
					let mut previous = '\0';
					for next in chars.by_ref() {
						if previous == '*' && next == '/' {
							break;
						}
						previous = next;
					}
				},
				_ => out.push(ch),
			},
			_ => out.push(ch),
		}
	}
	serde_json::from_str(&strip_trailing_commas(&out)).ok()
}

/// Legacy settings persisted in the `agent.db` `settings` table (key/value
/// JSON rows). Only the config migration reads it, exactly like
/// `AgentStorage.getSettings`.
fn legacy_db_settings() -> Option<Value> {
	let path = dirs::agent_dir().join("agent.db");
	if !path.is_file() {
		return None;
	}
	let connection = rusqlite::Connection::open_with_flags(
		&path,
		rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY | rusqlite::OpenFlags::SQLITE_OPEN_NO_MUTEX,
	)
	.ok()?;
	let mut statement = connection.prepare("SELECT key, value FROM settings").ok()?;
	let rows = statement
		.query_map([], |row| {
			let key: String = row.get(0)?;
			let value: String = row.get(1)?;
			Ok((key, value))
		})
		.ok()?;
	let mut pairs: Vec<(String, Value)> = Vec::new();
	for row in rows.flatten() {
		match serde_json::from_str::<Json>(&row.1) {
			Ok(json) => pairs.push((row.0, json_to_value(&json))),
			Err(err) => eprintln!("warning: skipping unreadable agent.db setting {}: {err}", row.0),
		}
	}
	if pairs.is_empty() {
		return None;
	}
	Some(Value::Map(pairs))
}

/// `#migrateFromLegacy`: fold `settings.json` (JSONC, renamed to `.bak`) and
/// the `agent.db` settings into a fresh `config.yml` before the first write.
fn seed_legacy_global(path: &Path) -> Result<Value> {
	let mut seeded = Value::Map(Vec::new());
	let mut migrated = false;
	let mut archived_source = None;
	if let Some(source) = read_legacy_source() {
		let mut legacy = source.value;
		migrate_settings(&mut legacy);
		if matches!(legacy, Value::Map(_)) {
			merge(&mut seeded, legacy);
			migrated = true;
			archived_source = Some((source.path, source.identity, source.link));
		}
	}
	if let Some(mut db) = legacy_db_settings() {
		migrate_settings(&mut db);
		merge(&mut seeded, db);
		migrated = true;
	}
	if migrated {
		if let Value::Map(pairs) = &seeded {
			if !pairs.is_empty() {
				// Write before archiving: a failed write must leave settings.json
				// in place so the next attempt still sees the legacy data.
				write_atomic(path, &yaml::to_string(&seeded))?;
			}
		}
	}
	if let Some((settings_json, identity, link)) = archived_source {
		archive_legacy_settings(&settings_json, identity, link)?;
	}
	Ok(seeded)
}

/// Archive `settings.json` without ever clobbering an existing file or relying
/// on hard links (Android SELinux denies them for app-private files): create the
/// first free `settings.json.bak[N]` exclusively, copy the bytes, fsync, then
/// remove the source only if its inode/size/mtime still match what we migrated.
/// A partially written backup is removed again before the error propagates.
fn archive_legacy_settings(
	settings_json: &Path,
	expected: (u64, u64, Option<SystemTime>),
	link: Option<PathBuf>,
) -> Result<()> {
	if let Some(target) = link {
		return archive_legacy_symlink(settings_json, expected, &target);
	}
	let bytes = fs::read(settings_json)
		.map_err(|err| Error::with_source(format!("cannot read {}", settings_json.display()), err))?;
	let base = settings_json.with_extension("json.bak");
	let mut backup = None;
	for index in 0..1000 {
		let candidate = if index == 0 {
			base.clone()
		} else {
			PathBuf::from(format!("{}.{index}", base.display()))
		};
		match OpenOptions::new().write(true).create_new(true).mode(0o600).open(&candidate) {
			Ok(file) => {
				backup = Some((candidate, file));
				break;
			},
			Err(err) if err.kind() == io::ErrorKind::AlreadyExists => {},
			Err(err) => {
				return Err(Error::with_source(
					format!("cannot archive {} to {}", settings_json.display(), candidate.display()),
					err,
				))
			},
		}
	}
	let Some((backup_path, mut file)) = backup else {
		return Err(Error::new(format!(
			"cannot archive {}: no free backup name",
			settings_json.display()
		)));
	};
	let written = file.write_all(&bytes).and_then(|()| file.sync_all());
	if let Err(err) = written {
		drop(file);
		let _ = fs::remove_file(&backup_path);
		return Err(Error::with_source(
			format!("cannot archive {} to {}", settings_json.display(), backup_path.display()),
			err,
		));
	}
	drop(file);
	// `expected` came from the opened handle, which follows symlinks, so the
	// recheck has to follow them too.
	let current = fs::metadata(settings_json).ok().map(|meta| {
		(meta.ino(), meta.len(), meta.modified().ok())
	});
	if current != Some(expected) {
		// config.yml already holds the bytes read earlier; failing loudly is the
		// only way to avoid silently dropping the concurrent edit.
		let _ = fs::remove_file(&backup_path);
		return Err(Error::new(format!(
			"{} changed while migrating; re-run to migrate the new contents",
			settings_json.display()
		)));
	}
	if let Err(err) = fs::remove_file(settings_json) {
		let _ = fs::remove_file(&backup_path);
		return Err(Error::with_source(
			format!("cannot remove {}", settings_json.display()),
			err,
		));
	}
	Ok(())
}

/// Symlinked `settings.json` (dotfile managers): upstream's rename moves the
/// link itself and leaves the target alone. Recreate the link under a free
/// `.bak` name, then unlink the source link once the target is still the same.
fn archive_legacy_symlink(settings_json: &Path, expected: (u64, u64, Option<SystemTime>), target: &Path) -> Result<()> {
	let base = settings_json.with_extension("json.bak");
	let mut backup = None;
	for index in 0..1000 {
		let candidate = if index == 0 {
			base.clone()
		} else {
			PathBuf::from(format!("{}.{index}", base.display()))
		};
		match std::os::unix::fs::symlink(target, &candidate) {
			Ok(()) => {
				backup = Some(candidate);
				break;
			},
			Err(err) if err.kind() == io::ErrorKind::AlreadyExists => {},
			Err(err) => {
				return Err(Error::with_source(
					format!("cannot archive {} to {}", settings_json.display(), candidate.display()),
					err,
				))
			},
		}
	}
	let Some(backup_path) = backup else {
		return Err(Error::new(format!(
			"cannot archive {}: no free backup name",
			settings_json.display()
		)));
	};
	let current = fs::metadata(settings_json).ok().map(|meta| {
		(meta.ino(), meta.len(), meta.modified().ok())
	});
	let same_target = fs::symlink_metadata(settings_json)
		.ok()
		.filter(|meta| meta.file_type().is_symlink())
		.and_then(|_| fs::read_link(settings_json).ok());
	if current != Some(expected) || same_target.as_deref() != Some(target) {
		let _ = fs::remove_file(&backup_path);
		return Err(Error::new(format!(
			"{} changed while migrating; re-run to migrate the new contents",
			settings_json.display()
		)));
	}
	if let Err(err) = fs::remove_file(settings_json) {
		let _ = fs::remove_file(&backup_path);
		return Err(Error::with_source(
			format!("cannot remove {}", settings_json.display()),
			err,
		));
	}
	Ok(())
}

/// `Settings.init()` migration, under the same lock the writer uses so the
/// absent-check, seed, write and archive form one critical section.
fn init_legacy_migration() -> Result<()> {
	let path = resolve_write_path(&global_config_path())?;
	if path.exists() {
		return Ok(());
	}
	if let Some(dir) = path.parent() {
		fs::create_dir_all(dir)
			.map_err(|err| Error::with_source(format!("cannot create {}", dir.display()), err))?;
	}
	let _lock = ConfigLock::acquire(&path)?;
	if path.exists() {
		return Ok(());
	}
	seed_legacy_global(&path).map(|_| ())
}

/// OpenCode expands `{env:VAR}` and `{file:path}` before parsing its config
/// (`discovery/opencode.ts:substituteConfigVars`). `{file:}` resolves against
/// the config's directory or `~`, is trimmed and JSON-escaped, and a token on a
/// `//` comment line stays verbatim.
fn substitute_config_vars(text: &str, config_path: &Path) -> String {
	let env_expanded = substitute_env_vars(text);
	if !env_expanded.contains("{file:") {
		return env_expanded;
	}
	let dir = config_path.parent().unwrap_or_else(|| Path::new("."));
	let mut out = String::with_capacity(env_expanded.len());
	let mut cursor = 0;
	while let Some(offset) = env_expanded[cursor..].find("{file:") {
		let start = cursor + offset;
		let Some(end_offset) = env_expanded[start..].find('}') else { break };
		let end = start + end_offset + 1;
		out.push_str(&env_expanded[cursor..start]);
		cursor = end;
		let token = &env_expanded[start..end];
		let line_start = env_expanded[..start].rfind('\n').map_or(0, |index| index + 1);
		if env_expanded[line_start..start].trim_start().starts_with("//") {
			out.push_str(token);
			continue;
		}
		let raw_path = &token["{file:".len()..token.len() - 1];
		let resolved = if let Some(rest) = raw_path.strip_prefix("~/") {
			dirs::home_dir().map(|home| home.join(rest))
		} else if raw_path.starts_with('/') {
			Some(PathBuf::from(raw_path))
		} else {
			Some(dir.join(raw_path))
		};
		let Some(resolved) = resolved else { continue };
		let Ok(contents) = fs::read_to_string(&resolved) else {
			eprintln!("warning: opencode config references a missing file {}", resolved.display());
			continue;
		};
		let escaped = Json::String(contents.trim().to_string()).to_string();
		out.push_str(&escaped[1..escaped.len() - 1]);
	}
	out.push_str(&env_expanded[cursor..]);
	out
}

/// `{env:VAR}` becomes the value, or an empty string when unset.
fn substitute_env_vars(text: &str) -> String {
	let mut out = String::with_capacity(text.len());
	let mut cursor = 0;
	while let Some(offset) = text[cursor..].find("{env:") {
		let start = cursor + offset;
		let Some(end_offset) = text[start..].find('}') else { break };
		let end = start + end_offset + 1;
		out.push_str(&text[cursor..start]);
		let name = &text[start + "{env:".len()..end - 1];
		out.push_str(&std::env::var(name).unwrap_or_default());
		cursor = end;
	}
	out.push_str(&text[cursor..]);
	out
}

/// Drop the comma that precedes a closing `]`/`}` outside string literals,
/// which `JSONC.parse` accepts and plain JSON does not.
fn strip_trailing_commas(text: &str) -> String {
	let mut out = String::with_capacity(text.len());
	let mut chars = text.char_indices().peekable();
	let mut in_string = false;
	let mut escaped = false;
	while let Some((_, ch)) = chars.next() {
		if in_string {
			out.push(ch);
			if escaped {
				escaped = false;
			} else if ch == '\\' {
				escaped = true;
			} else if ch == '"' {
				in_string = false;
			}
			continue;
		}
		if ch == '"' {
			in_string = true;
			out.push(ch);
			continue;
		}
		if ch == ',' {
			let mut ahead = chars.clone();
			let mut next_significant = None;
			for (_, peeked) in ahead.by_ref() {
				if peeked.is_whitespace() {
					continue;
				}
				next_significant = Some(peeked);
				break;
			}
			if matches!(next_significant, Some(']' | '}')) {
				continue;
			}
		}
		out.push(ch);
	}
	out
}

/// `modelRoleValueFromUnknown` drops any project role that is neither a string
/// nor an array of strings before the merge.
fn filter_project_model_roles(layer: &mut Value) {
	let Value::Map(pairs) = layer else { return };
	let Some((_, Value::Map(roles))) = pairs.iter_mut().find(|(key, _)| key == "modelRoles") else {
		return;
	};
	roles.retain(|(_, value)| match value {
		Value::Str(_) => true,
		Value::List(items) => items.iter().all(|item| matches!(item, Value::Str(_))),
		_ => false,
	});
}

fn map_get_mut<'a>(pairs: &'a mut Vec<(String, Value)>, key: &str) -> Option<&'a mut Value> {
	pairs.iter_mut().find(|(existing, _)| existing == key).map(|(_, value)| value)
}

fn map_take(pairs: &mut Vec<(String, Value)>, key: &str) -> Option<Value> {
	pairs
		.iter()
		.position(|(existing, _)| existing == key)
		.map(|index| pairs.remove(index).1)
}

fn map_set(pairs: &mut Vec<(String, Value)>, key: &str, value: Value) {
	match map_get_mut(pairs, key) {
		Some(slot) => *slot = value,
		None => pairs.push((key.to_string(), value)),
	}
}

fn ensure_map<'a>(pairs: &'a mut Vec<(String, Value)>, key: &str) -> &'a mut Vec<(String, Value)> {
	if !matches!(map_get_mut(pairs, key), Some(Value::Map(_))) {
		map_set(pairs, key, Value::Map(Vec::new()));
	}
	match map_get_mut(pairs, key) {
		Some(Value::Map(inner)) => inner,
		_ => unreachable!("just installed a mapping"),
	}
}

fn str_value(value: Option<&mut Value>) -> Option<&str> {
	match value {
		Some(Value::Str(text)) => Some(text.as_str()),
		_ => None,
	}
}

/// Port of `#migrateRawSettings`: legacy keys become the current schema shape
/// before any layer is merged or read.
fn migrate_settings(raw: &mut Value) {
	let Value::Map(root) = raw else { return };
	// queueMode -> steeringMode
	if !root.iter().any(|(key, _)| key == "steeringMode") {
		if let Some(value) = map_take(root, "queueMode") {
			map_set(root, "steeringMode", value);
		}
	}
	map_take(root, "lastChangelogVersion");
	// collapseChangelog -> startup.changelogMode
	let flat_changelog_mode = match str_value(map_get_mut(root, "startup.changelogMode")) {
		Some(mode @ ("summary" | "expanded" | "hidden")) => Some(mode.to_string()),
		_ => None,
	};
	let legacy_collapse = match root.iter().find(|(key, _)| key == "collapseChangelog").map(|(_, v)| v) {
		Some(Value::Bool(flag)) => Some(*flag),
		_ => None,
	};
	if legacy_collapse.is_some() || flat_changelog_mode.is_some() {
		let startup = ensure_map(root, "startup");
		if startup.iter().all(|(key, _)| key != "changelogMode") {
			if let Some(mode) = flat_changelog_mode
				.or_else(|| legacy_collapse.map(|flag| if flag { "summary" } else { "expanded" }).map(str::to_string))
			{
				map_set(startup, "changelogMode", Value::Str(mode));
			}
		}
	}
	map_take(root, "collapseChangelog");
	map_take(root, "startup.changelogMode");
	// ask.timeout: milliseconds -> seconds
	if let Some(Value::Map(ask)) = map_get_mut(root, "ask") {
		if let Some(Value::Int(ms)) = map_get_mut(ask, "timeout") {
			if *ms > 1000 {
				*ms = (*ms + 500) / 1000;
			}
		}
	}
	// Flat theme string -> theme.dark/theme.light; built-in names just drop.
	// Only the string form is migrated: a nested `theme` object is user data and
	// must survive (upstream deletes the key inside the string branch only).
	let flat_theme = match map_get_mut(root, "theme") {
		Some(Value::Str(theme)) => Some(theme.clone()),
		_ => None,
	};
	if let Some(theme) = flat_theme {
		map_take(root, "theme");
		if theme != "light" && theme != "dark" {
			let slot = if theme_is_light(&theme) { "light" } else { "dark" };
			let mut nested = Vec::new();
			nested.push((slot.to_string(), Value::Str(theme)));
			map_set(root, "theme", Value::Map(nested));
		}
	}
	// inspect_image.enabled -> inspect_image.mode
	let inspect_legacy = match root.iter().find(|(key, _)| key == "inspect_image.enabled").map(|(_, v)| v) {
		Some(Value::Bool(flag)) => Some(*flag),
		_ => None,
	}
	.or_else(|| match map_get_mut(root, "inspect_image") {
		Some(Value::Map(inner)) => inner.iter().find(|(key, _)| key == "enabled").and_then(|(_, v)| match v {
			Value::Bool(flag) => Some(*flag),
			_ => None,
		}),
		_ => None,
	});
	if let Some(flag) = inspect_legacy {
		let flat_mode = str_value(map_get_mut(root, "inspect_image.mode")).map(str::to_string);
		let target = ensure_map(root, "inspect_image");
		if target.iter().all(|(key, _)| key != "mode") {
			let mode = flat_mode
				.filter(|mode| matches!(mode.as_str(), "auto" | "on" | "off"))
				.unwrap_or_else(|| if flag { "on" } else { "off" }.to_string());
			map_set(target, "mode", Value::Str(mode));
		}
		if let Some(Value::Map(inner)) = map_get_mut(root, "inspect_image") {
			map_take(inner, "enabled");
		}
		map_take(root, "inspect_image.enabled");
		map_take(root, "inspect_image.mode");
	}
	// task.isolation.enabled -> task.isolation.mode, then legacy mode names.
	if let Some(Value::Map(task)) = map_get_mut(root, "task") {
		if let Some(Value::Map(isolation)) = map_get_mut(task, "isolation") {
			if let Some(Value::Bool(enabled)) = map_take(isolation, "enabled") {
				map_set(isolation, "mode", Value::Str((if enabled { "auto" } else { "none" }).into()));
			}
			if let Some(Value::Str(mode)) = map_get_mut(isolation, "mode") {
				let mapped = match mode.as_str() {
					"worktree" => Some("rcopy"),
					"fuse-overlay" => Some("overlayfs"),
					"fuse-projfs" => Some("projfs"),
					_ => None,
				};
				if let Some(mapped) = mapped {
					*mode = mapped.to_string();
				}
			}
		}
		map_take(task, "simple");
		// Upstream converts only booleans and leaves anything else untouched.
		let task_eager = match map_get_mut(task, "eager") {
			Some(Value::Bool(flag)) => Some(*flag),
			_ => None,
		};
		if let Some(eager) = task_eager {
			map_take(task, "eager");
			map_set(task, "eager", Value::Str((if eager { "always" } else { "default" }).into()));
		}
	}
	if let Some(Value::Map(todo)) = map_get_mut(root, "todo") {
		let todo_eager = match map_get_mut(todo, "eager") {
			Some(Value::Bool(flag)) => Some(*flag),
			_ => None,
		};
		if let Some(eager) = todo_eager {
			map_take(todo, "eager");
			map_set(todo, "eager", Value::Str((if eager { "always" } else { "default" }).into()));
		}
	}
	// features.unexpectedStopDetection -> enum none|mechanical|smart
	let legacy_stop = match root.iter().find(|(key, _)| key == "features.unexpectedStopDetection").map(|(_, v)| v) {
		Some(Value::Bool(flag)) => Some(*flag),
		_ => None,
	}
	.or_else(|| match map_get_mut(root, "features") {
		Some(Value::Map(inner)) => inner
			.iter()
			.find(|(key, _)| key == "unexpectedStopDetection")
			.and_then(|(_, v)| match v {
				Value::Bool(flag) => Some(*flag),
				_ => None,
			}),
		_ => None,
	});
	if let Some(flag) = legacy_stop {
		let current_is_mode = match map_get_mut(root, "features") {
			Some(Value::Map(features)) => matches!(
				features.iter().find(|(key, _)| key == "unexpectedStopDetection").map(|(_, v)| v),
				Some(Value::Str(mode)) if matches!(mode.as_str(), "none" | "mechanical" | "smart")
			),
			_ => false,
		};
		if !current_is_mode {
			let features = ensure_map(root, "features");
			map_set(
				features,
				"unexpectedStopDetection",
				Value::Str((if flag { "smart" } else { "none" }).into()),
			);
		}
		map_take(root, "features.unexpectedStopDetection");
	}
	// edit.mode atom|vim -> hashline (including modelVariants values)
	if let Some(Value::Map(edit)) = map_get_mut(root, "edit") {
		if let Some(Value::Str(mode)) = map_get_mut(edit, "mode") {
			if mode.as_str() == "atom" || mode.as_str() == "vim" {
				*mode = "hashline".into();
			}
		}
		if let Some(Value::Map(variants)) = map_get_mut(edit, "modelVariants") {
			for (_, variant) in variants.iter_mut() {
				if let Value::Str(name) = variant {
					if name == "atom" || name == "vim" {
						*name = "hashline".into();
					}
				}
			}
		}
	}
	if let Some(Value::Str(mode)) = map_get_mut(root, "edit.mode") {
		if mode.as_str() == "atom" || mode.as_str() == "vim" {
			*mode = "hashline".into();
		}
	}
	// compaction.strategy / remoteEnabled -> methodOrder
	let configured_order = map_get_mut(root, "compaction")
		.and_then(|value| match value {
			Value::Map(inner) => inner.iter().find(|(key, _)| key == "methodOrder").map(|(_, v)| v.clone()),
			_ => None,
		})
		.or_else(|| map_get_mut(root, "compaction.methodOrder").map(|value| value.clone()));
	let legacy_strategy = map_get_mut(root, "compaction")
		.and_then(|value| match value {
			Value::Map(inner) => inner.iter().find(|(key, _)| key == "strategy").map(|(_, v)| v.clone()),
			_ => None,
		})
		.or_else(|| map_get_mut(root, "compaction.strategy").map(|value| value.clone()));
	let legacy_remote = map_get_mut(root, "compaction")
		.and_then(|value| match value {
			Value::Map(inner) => inner.iter().find(|(key, _)| key == "remoteEnabled").map(|(_, v)| v.clone()),
			_ => None,
		})
		.or_else(|| map_get_mut(root, "compaction.remoteEnabled").map(|value| value.clone()));
	if !matches!(configured_order, Some(Value::List(_))) {
		let remote_enabled = !matches!(legacy_remote, Some(Value::Bool(false)));
		let strategy = match legacy_strategy {
			Some(Value::Str(name)) if name == "shake-summary" => Some("shake".to_string()),
			Some(Value::Str(name)) => Some(name),
			_ => None,
		};
		let order = match strategy.as_deref() {
			Some("context-full") => Some(if remote_enabled { vec!["remote", "soft"] } else { vec!["soft"] }),
			Some("handoff") => Some(if remote_enabled {
				vec!["handoff", "remote", "soft"]
			} else {
				vec!["handoff", "soft"]
			}),
			Some("shake") => Some(if remote_enabled {
				vec!["shake", "remote", "soft"]
			} else {
				vec!["shake", "soft"]
			}),
			Some("snapcompact") => Some(if remote_enabled {
				vec!["snapcompact", "remote", "soft"]
			} else {
				vec!["snapcompact", "soft"]
			}),
			Some("off") => Some(Vec::new()),
			_ => None,
		};
		if let Some(order) = order {
			let compaction = ensure_map(root, "compaction");
			let list = order.into_iter().map(|name| Value::Str(name.into())).collect();
			map_set(compaction, "methodOrder", Value::List(list));
		}
	}
	if let Some(Value::Map(compaction)) = map_get_mut(root, "compaction") {
		map_take(compaction, "strategy");
		map_take(compaction, "remoteEnabled");
	}
	map_take(root, "compaction.strategy");
	map_take(root, "compaction.remoteEnabled");
	map_take(root, "compaction.methodOrder");
	// snapcompact.systemPrompt boolean -> enum
	for holder in ["snapcompact", "snapcompact.systemPrompt"] {
		let flag = match map_get_mut(root, holder) {
			Some(Value::Map(inner)) => match map_get_mut(inner, "systemPrompt") {
				Some(Value::Bool(flag)) => Some(*flag),
				_ => None,
			},
			Some(Value::Bool(flag)) => Some(*flag),
			_ => None,
		};
		let Some(flag) = flag else { continue };
		let replacement = Value::Str((if flag { "all" } else { "none" }).into());
		if holder == "snapcompact" {
			if let Some(Value::Map(inner)) = map_get_mut(root, holder) {
				map_set(inner, "systemPrompt", replacement);
			}
		} else {
			map_set(root, holder, replacement);
		}
	}
	// inlineToolDescriptors boolean -> on|off
	let inline_tool_descriptors = match map_get_mut(root, "inlineToolDescriptors") {
		Some(Value::Bool(flag)) => Some(*flag),
		_ => None,
	};
	if let Some(flag) = inline_tool_descriptors {
		let replacement = Value::Str((if flag { "on" } else { "off" }).into());
		map_set(root, "inlineToolDescriptors", replacement);
	}
	// statusLine plan_mode segment -> mode
	if let Some(Value::Map(status_line)) = map_get_mut(root, "statusLine") {
		for key in ["leftSegments", "rightSegments"] {
			if let Some(Value::List(segments)) = map_get_mut(status_line, key) {
				for segment in segments.iter_mut() {
					if matches!(segment, Value::Str(name) if name == "plan_mode") {
						*segment = Value::Str("mode".into());
					}
				}
			}
		}
		if let Some(Value::Map(options)) = map_get_mut(status_line, "segmentOptions") {
			let legacy = options.iter().find(|(key, _)| key == "plan_mode").map(|(_, v)| v.clone());
			if let Some(legacy) = legacy {
				if options.iter().all(|(key, _)| key != "mode") {
					map_set(options, "mode", legacy);
				}
				map_take(options, "plan_mode");
			}
		}
	}
	// providers.parallelFetch dropped
	if let Some(Value::Map(providers)) = map_get_mut(root, "providers") {
		map_take(providers, "parallelFetch");
	}
	map_take(root, "providers.parallelFetch");
	// codexResets.autoRedeem boolean -> yes|no
	let auto_redeem = match map_get_mut(root, "codexResets") {
		Some(Value::Map(codex)) => match map_get_mut(codex, "autoRedeem") {
			Some(Value::Bool(flag)) => Some(*flag),
			_ => None,
		},
		_ => None,
	};
	if let Some(flag) = auto_redeem {
		if let Some(Value::Map(codex)) = map_get_mut(root, "codexResets") {
			map_set(
				codex,
				"autoRedeem",
				Value::Str((if flag { "yes" } else { "no" }).into()),
			);
		}
	}
	let flat_auto_redeem = match map_get_mut(root, "codexResets.autoRedeem") {
		Some(Value::Bool(flag)) => Some(*flag),
		_ => None,
	};
	if let Some(flag) = flat_auto_redeem {
		let replacement = Value::Str((if flag { "yes" } else { "no" }).into());
		map_set(root, "codexResets.autoRedeem", replacement);
	}
	// memories.enabled -> memory.backend
	let backend_set = matches!(
		map_get_mut(root, "memory"),
		Some(Value::Map(inner)) if matches!(inner.iter().find(|(key, _)| key == "backend").map(|(_, v)| v), Some(Value::Str(_)))
	);
	let legacy_memories = match map_get_mut(root, "memories") {
		Some(Value::Map(inner)) => inner.iter().find(|(key, _)| key == "enabled").and_then(|(_, v)| match v {
			Value::Bool(flag) => Some(*flag),
			_ => None,
		}),
		_ => None,
	};
	if !backend_set {
		if let Some(enabled) = legacy_memories {
			let memory = ensure_map(root, "memory");
			map_set(memory, "backend", Value::Str((if enabled { "local" } else { "off" }).into()));
		}
	}
	// mnemosyne -> mnemopi
	if let Some(Value::Map(memory)) = map_get_mut(root, "memory") {
		if let Some(Value::Str(backend)) = map_get_mut(memory, "backend") {
			if backend.as_str() == "mnemosyne" {
				*backend = "mnemopi".into();
			}
		}
	}
	if root.iter().any(|(key, _)| key == "mnemosyne") && root.iter().all(|(key, _)| key != "mnemopi") {
		if let Some(value) = map_take(root, "mnemosyne") {
			map_set(root, "mnemopi", value);
		}
	}
	// hindsight.dynamicBankId / agentName -> scoping / bankId
	if let Some(Value::Map(hindsight)) = map_get_mut(root, "hindsight") {
		let dynamic = hindsight.iter().find(|(key, _)| key == "dynamicBankId").map(|(_, v)| v.clone());
		if let Some(dynamic) = dynamic {
			let scoping_set = hindsight.iter().any(|(key, _)| key == "scoping");
			if !scoping_set && matches!(dynamic, Value::Bool(true)) {
				map_set(hindsight, "scoping", Value::Str("per-project".into()));
			}
			map_take(hindsight, "dynamicBankId");
		}
		let agent_name = hindsight.iter().find(|(key, _)| key == "agentName").map(|(_, v)| v.clone());
		if let Some(agent_name) = agent_name {
			let bank_set = hindsight.iter().any(|(key, _)| key == "bankId");
			if let Value::Str(name) = &agent_name {
				let trimmed = name.trim();
				if !bank_set && !trimmed.is_empty() && trimmed != "omp" {
					map_set(hindsight, "bankId", Value::Str(trimmed.to_string()));
				}
			}
			map_take(hindsight, "agentName");
		}
	}
	migrate_settings_tail(root);
}

